  // Strip obvious PII before anything leaves the browser. Addresses are not detected.
  var EMAIL_RE = /[^\s@]+@[^\s@]+\.[^\s@]+/g;
  var PHONE_RE = /\+?\d[\d\s().-]{7,}\d/g;
